import pandas as pd

def calculate_turn_scores(rolls):
    scores = []

    # 1. High and Often
    max_roll = max(rolls)
    scores.append(max_roll * rolls.count(max_roll))

    # 2. Summation
    scores.append(sum(rolls))

    # 3. Highs and Lows
    min_roll = min(rolls)
    scores.append(max_roll * min_roll * (max_roll - min_roll))

    # 4. Only two numbers
    if len(set(rolls)) <= 2:
        scores.append(30)
    else:
        scores.append(0)

    # 5. All the numbers
    if len(set(rolls)) == 6:
        scores.append(40)
    else:
        scores.append(0)

    # 6. Ordered subset of four
    found_ordered = False
    for i in range(3):
        subset = rolls[i:i+4]
        if all(subset[j+1] == subset[j] + 1 for j in range(3)):
            found_ordered = True
            break
        if all(subset[j+1] == subset[j] - 1 for j in range(3)):
            found_ordered = True
            break
    if found_ordered:
        scores.append(50)
    else:
        scores.append(0)

    return scores

def get_game_score(turn1_rolls, turn2_rolls):
    s1 = calculate_turn_scores(turn1_rolls)
    s2 = calculate_turn_scores(turn2_rolls)

    max_score = 0
    for i in range(6):
        for j in range(6):
            if i == j:
                continue
            score = s1[i] + s2[j]
            if score > max_score:
                max_score = score
    return max_score

df = pd.read_excel('/root/data.xlsx', sheet_name='Data', skiprows=8, header=None)
turns = []
for index, row in df.iterrows():
    if pd.isna(row[3]): continue
    try:
        game_num = int(row[3])
        turn_num = int(row[2])
        rolls = [int(row[i]) for i in range(4, 10)]
        turns.append((game_num, turn_num, rolls))
    except:
        continue

games = {}
for g_num, t_num, rolls in turns:
    if g_num not in games:
        games[g_num] = {}
    games[g_num][t_num] = rolls

game_scores = {}
for g_num in sorted(games.keys()):
    if 1 in games[g_num] and 2 in games[g_num]:
        t1 = games[g_num][1]
        t2 = games[g_num][2]
        game_scores[g_num] = get_game_score(t1, t2)

p1_wins = 0
p2_wins = 0
num_matches = len(game_scores) // 2
for i in range(1, num_matches + 1):
    g1_num = 2*i - 1
    g2_num = 2*i
    if g1_num in game_scores and g2_num in game_scores:
        s1 = game_scores[g1_num]
        s2 = game_scores[g2_num]
        if s1 > s2:
            p1_wins += 1
        elif s2 > s1:
            p2_wins += 1

print(p1_wins - p2_wins)

